{
  "name": "ShopeeLink AI Pro",
  "description": "Convert Shopee product links into affiliate links instantly and generate AI-powered marketing captions using Gemini."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface UserSettings {
  affiliateId: string;
  subId?: string;
  universalLinkEnabled: boolean;
}

export interface ConvertedLink {
  originalUrl: string;
  affiliateUrl: string;
  timestamp: number;
  productName?: string;
}

export interface MarketingContent {
  caption: string;
  hashtags: string[];
}

export type Platform = 'facebook' | 'tiktok' | 'instagram' | 'twitter';

import { GoogleGenAI, Type } from "@google/genai";
import { Platform, MarketingContent } from "../types";

const apiKey = process.env.API_KEY || '';

// Initialize Gemini Client
// Note: In a production environment, API calls should be proxied through a backend to protect the key.
// For this frontend-only demo, we assume the environment variable is injected safely.
const ai = new GoogleGenAI({ apiKey });

export const generateMarketingCopy = async (
  productUrl: string,
  platform: Platform
): Promise<MarketingContent> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Extract a potential product name from the slug to help the AI context
  // e.g., shopee.vn/Ao-thun-nam-dep-i.123.456 -> "Ao thun nam dep"
  let contextHint = "Unknown Product";
  try {
    const urlObj = new URL(productUrl);
    const pathSegments = urlObj.pathname.split('/');
    const slug = pathSegments.find(s => s.length > 5 && s.includes('-'));
    if (slug) {
      // Remove the ID part at the end (usually after the last dash or 'i.')
      contextHint = slug.split('.')[0].replace(/-/g, ' ');
    }
  } catch (e) {
    console.warn("Could not parse URL for context hint", e);
  }

  const prompt = `
    I have a Shopee product link: ${productUrl}. 
    Based on the URL structure, the product seems to be: "${contextHint}".

    Please act as an expert social media marketer. Write a catchy, engaging, and high-converting caption for this product for ${platform}.

    Requirements:
    1. Language: Vietnamese.
    2. Tone: Enthusiastic, urgency (FOMO), and friendly.
    3. Include emojis relevant to the product.
    4. Include 5-8 relevant hashtags.
    5. The output must be JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            caption: {
              type: Type.STRING,
              description: "The main body of the social media post.",
            },
            hashtags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "A list of hashtags without the hash symbol.",
            }
          },
          required: ["caption", "hashtags"],
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini");
    }

    const data = JSON.parse(text);
    return {
      caption: data.caption,
      hashtags: data.hashtags.map((tag: string) => tag.startsWith('#') ? tag : `#${tag}`),
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback in case of error
    return {
      caption: `🔥 Deal hot trên Shopee ngay lúc này! Mọi người nhanh tay check ngay sản phẩm "${contextHint}" này nhé. Giá siêu tốt, chất lượng tuyệt vời! 👇`,
      hashtags: ["#Shopee", "#Sale", "#DealHot", "#MuaSamOnline"]
    };
  }
};

import React, { useState, useEffect } from 'react';
import { X, Save, AlertCircle } from 'lucide-react';
import { UserSettings } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: UserSettings;
  onSave: (settings: UserSettings) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  settings,
  onSave,
}) => {
  const [formData, setFormData] = useState<UserSettings>(settings);

  useEffect(() => {
    setFormData(settings);
  }, [settings, isOpen]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSave = () => {
    onSave(formData);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in">
        <div className="flex justify-between items-center p-4 border-b border-gray-100">
          <h2 className="text-xl font-bold text-gray-800">Cấu hình Affiliate</h2>
          <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-full transition">
            <X className="w-6 h-6 text-gray-500" />
          </button>
        </div>

        <div className="p-6 space-y-4">
          <div className="bg-orange-50 p-3 rounded-lg flex gap-3 items-start">
            <AlertCircle className="w-5 h-5 text-shopee shrink-0 mt-0.5" />
            <p className="text-sm text-gray-700">
              Nhập Affiliate ID (hoặc username) của bạn. Hệ thống sẽ tự động gắn tag này vào link Shopee.
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Affiliate ID / Username</label>
            <input
              type="text"
              name="affiliateId"
              value={formData.affiliateId}
              onChange={handleChange}
              placeholder="VD: my_affiliate_id"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-shopee focus:border-transparent outline-none transition"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Sub ID (Tuỳ chọn)</label>
            <input
              type="text"
              name="subId"
              value={formData.subId || ''}
              onChange={handleChange}
              placeholder="VD: facebook_campaign_1"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-shopee focus:border-transparent outline-none transition"
            />
          </div>

          <div className="flex items-center gap-3 pt-2">
            <input
              type="checkbox"
              id="universalLinkEnabled"
              name="universalLinkEnabled"
              checked={formData.universalLinkEnabled}
              onChange={handleChange}
              className="w-5 h-5 text-shopee rounded focus:ring-shopee border-gray-300"
            />
            <label htmlFor="universalLinkEnabled" className="text-sm text-gray-700 cursor-pointer select-none">
              Sử dụng định dạng Universal Link (Khuyên dùng)
            </label>
          </div>
        </div>

        <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50">
          <button
            onClick={onClose}
            className="px-4 py-2 text-gray-600 font-medium hover:text-gray-800 transition"
          >
            Hủy
          </button>
          <button
            onClick={handleSave}
            className="px-6 py-2 bg-shopee hover:bg-shopee-dark text-white rounded-lg font-medium shadow-md shadow-orange-200 flex items-center gap-2 transition transform active:scale-95"
          >
            <Save className="w-4 h-4" />
            Lưu Cấu Hình
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Copy, Check, ExternalLink, Wand2, RefreshCw } from 'lucide-react';
import { ConvertedLink, MarketingContent, Platform } from '../types';
import { generateMarketingCopy } from '../services/geminiService';

interface ResultCardProps {
  result: ConvertedLink;
}

export const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [copied, setCopied] = useState(false);
  const [copiedText, setCopiedText] = useState(false);

  const [marketingContent, setMarketingContent] = useState<MarketingContent | null>(null);
  const [loadingAI, setLoadingAI] = useState(false);
  const [platform, setPlatform] = useState<Platform>('facebook');

  const handleCopy = (text: string, isUrl: boolean) => {
    navigator.clipboard.writeText(text);
    if (isUrl) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } else {
      setCopiedText(true);
      setTimeout(() => setCopiedText(false), 2000);
    }
  };

  const handleGenerateAI = async () => {
    setLoadingAI(true);
    try {
      const content = await generateMarketingCopy(result.originalUrl, platform);
      setMarketingContent(content);
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingAI(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden animate-slide-up">
      {/* Header */}
      <div className="bg-gray-50 p-4 border-b border-gray-100 flex items-center justify-between">
        <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Link Affiliate Của Bạn</span>
        <span className="text-xs text-gray-400">{new Date(result.timestamp).toLocaleTimeString()}</span>
      </div>

      {/* Main Link Area */}
      <div className="p-6">
        <div className="flex flex-col sm:flex-row gap-4 items-center">
          <div className="flex-1 w-full relative">
            <input
              readOnly
              value={result.affiliateUrl}
              className="w-full bg-orange-50 text-gray-800 border-2 border-orange-100 rounded-lg px-4 py-3 pr-12 font-mono text-sm focus:outline-none"
            />
            <a 
              href={result.affiliateUrl} 
              target="_blank" 
              rel="noreferrer"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-shopee"
              title="Mở link"
            >
              <ExternalLink className="w-4 h-4" />
            </a>
          </div>
          <button
            onClick={() => handleCopy(result.affiliateUrl, true)}
            className={`w-full sm:w-auto px-6 py-3 rounded-lg font-semibold flex items-center justify-center gap-2 transition-all duration-200 ${
              copied 
                ? 'bg-green-500 text-white shadow-green-200' 
                : 'bg-shopee text-white hover:bg-shopee-dark shadow-orange-200'
            } shadow-md`}
          >
            {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
            {copied ? 'Đã Copy' : 'Copy Link'}
          </button>
        </div>

        {/* AI Section */}
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              <Wand2 className="w-5 h-5 text-purple-600" />
              Tạo Caption Bán Hàng (AI)
            </h3>

            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg">
              {(['facebook', 'tiktok', 'instagram'] as Platform[]).map((p) => (
                <button
                  key={p}
                  onClick={() => setPlatform(p)}
                  className={`px-3 py-1.5 rounded-md text-xs font-medium capitalize transition ${
                    platform === p ? 'bg-white shadow text-gray-900' : 'text-gray-500 hover:text-gray-700'
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>

          {!marketingContent && !loadingAI && (
             <div className="bg-purple-50 rounded-xl p-6 text-center border border-purple-100">
               <p className="text-purple-800 mb-4 font-medium">Sử dụng Gemini để viết content bán hàng tự động cho link này.</p>
               <button
                 onClick={handleGenerateAI}
                 className="px-6 py-2.5 bg-purple-600 hover:bg-purple-700 text-white rounded-full font-medium shadow-md shadow-purple-200 flex items-center gap-2 mx-auto transition transform hover:scale-105"
               >
                 <Wand2 className="w-4 h-4" />
                 Viết Content Ngay
               </button>
             </div>
          )}

          {loadingAI && (
            <div className="bg-gray-50 rounded-xl p-8 flex flex-col items-center justify-center animate-pulse">
              <RefreshCw className="w-8 h-8 text-purple-500 animate-spin mb-3" />
              <p className="text-gray-500 font-medium">Gemini đang phân tích sản phẩm và viết bài...</p>
            </div>
          )}

          {marketingContent && !loadingAI && (
            <div className="bg-white rounded-xl border border-purple-100 shadow-sm overflow-hidden">
               <div className="p-4 bg-purple-50 border-b border-purple-100 flex justify-between items-center">
                 <span className="text-xs font-bold text-purple-700 uppercase">Gemini Output ({platform})</span>
                 <button 
                  onClick={() => handleCopy(`${marketingContent.caption}\n\n${marketingContent.hashtags.join(' ')}\n\nLink mua: ${result.affiliateUrl}`, false)}
                  className="text-purple-600 hover:text-purple-800 text-xs font-medium flex items-center gap-1"
                 >
                   {copiedText ? <Check className="w-3 h-3"/> : <Copy className="w-3 h-3"/>}
                   {copiedText ? 'Đã sao chép' : 'Sao chép toàn bộ'}
                 </button>
               </div>
               <div className="p-5">
                 <p className="text-gray-800 whitespace-pre-line leading-relaxed mb-4 text-sm sm:text-base">
                   {marketingContent.caption}
                 </p>
                 <div className="flex flex-wrap gap-2 text-sm text-blue-600 font-medium">
                   {marketingContent.hashtags.join(' ')}
                 </div>
                 <div className="mt-4 pt-4 border-t border-dashed border-gray-200 text-sm text-gray-500">
                   Link mua: <span className="text-shopee font-mono">{result.affiliateUrl}</span>
                 </div>
               </div>
               <div className="bg-gray-50 p-3 text-center">
                  <button 
                    onClick={handleGenerateAI}
                    className="text-gray-500 hover:text-purple-600 text-sm font-medium flex items-center justify-center gap-2 mx-auto"
                  >
                    <RefreshCw className="w-4 h-4" />
                    Viết lại phiên bản khác
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Settings, Link as LinkIcon, ShoppingBag, Zap } from 'lucide-react';
import { SettingsModal } from './components/SettingsModal';
import { ResultCard } from './components/ResultCard';
import { UserSettings, ConvertedLink } from './types';

// Constants
const DEFAULT_SETTINGS: UserSettings = {
  affiliateId: '',
  universalLinkEnabled: true,
};

const STORAGE_KEY = 'shopee_link_settings';
const HISTORY_KEY = 'shopee_link_history';

function App() {
  const [urlInput, setUrlInput] = useState('');
  const [settings, setSettings] = useState<UserSettings>(DEFAULT_SETTINGS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [currentResult, setCurrentResult] = useState<ConvertedLink | null>(null);
  const [history, setHistory] = useState<ConvertedLink[]>([]);
  const [error, setError] = useState('');

  // Load settings and history on mount
  useEffect(() => {
    const savedSettings = localStorage.getItem(STORAGE_KEY);
    if (savedSettings) {
      setSettings(JSON.parse(savedSettings));
    }
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      setHistory(JSON.parse(savedHistory));
    }
  }, []);

  const saveSettings = (newSettings: UserSettings) => {
    setSettings(newSettings);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newSettings));
  };

  const convertLink = () => {
    setError('');

    // Basic validation
    if (!urlInput.trim()) {
      setError('Vui lòng nhập link Shopee');
      return;
    }
    if (!urlInput.includes('shopee') && !urlInput.includes('shp.ee')) {
      setError('Link không hợp lệ. Vui lòng nhập link Shopee (shopee.vn hoặc shp.ee)');
      return;
    }
    if (!settings.affiliateId) {
      setError('Bạn chưa cấu hình Affiliate ID. Vui lòng vào Cài đặt.');
      setIsSettingsOpen(true);
      return;
    }

    // --- CONVERSION LOGIC ---
    // Note: A purely frontend conversion without API access is limited to adding UTM parameters 
    // or constructing Universal Links if the platform supports a standard format.
    // Real Shopee Affiliate conversion usually requires an API signature.
    // Here we simulate the "Best Practice" manual construction if API is unavailable.

    let affiliateUrl = '';

    if (settings.universalLinkEnabled) {
      // Construction for Universal Link (Deep Link) pattern
      // Often looks like: https://shopee.vn/universal-link/[slug]?referrer=[aff_id]

      // Try to extract clean URL first
      try {
        const urlObj = new URL(urlInput);

        // Handle short links (shp.ee) - In a real app, we might need to resolve headers, 
        // but here we just append params if it's a direct product link
        if (urlInput.includes('shp.ee')) {
           // Short links are tricky without backend resolution. 
           // We will just append the param which sometimes works or redirect works.
           const separator = urlInput.includes('?') ? '&' : '?';
           affiliateUrl = `${urlInput}${separator}utm_source=${settings.affiliateId}`;
        } else {
           // Standard shopee.vn link
           // Remove existing query params to clean it up
           const path = urlObj.pathname;
           // Universal Link base
           const baseUniversal = 'https://shopee.vn/universal-link';

           // Construct new params
           const params = new URLSearchParams();
           params.append('utm_source', settings.affiliateId);
           if (settings.subId) params.append('utm_content', settings.subId);
           params.append('deep_and_deferred', '1');

           // For simple simulation, we act as if we are wrapping the path
           affiliateUrl = `${baseUniversal}${path}?${params.toString()}`;
        }
      } catch (e) {
        // Fallback simple append
        const separator = urlInput.includes('?') ? '&' : '?';
        affiliateUrl = `${urlInput}${separator}utm_source=${settings.affiliateId}`;
      }
    } else {
      // Simple UTM Append
      const separator = urlInput.includes('?') ? '&' : '?';
      let suffix = `utm_source=${settings.affiliateId}`;
      if (settings.subId) suffix += `&utm_content=${settings.subId}`;
      affiliateUrl = `${urlInput}${separator}${suffix}`;
    }

    const newResult: ConvertedLink = {
      originalUrl: urlInput,
      affiliateUrl: affiliateUrl,
      timestamp: Date.now(),
    };

    setCurrentResult(newResult);

    // Update history
    const newHistory = [newResult, ...history].slice(0, 10); // Keep last 10
    setHistory(newHistory);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
  };

  const handleClearHistory = () => {
    setHistory([]);
    localStorage.removeItem(HISTORY_KEY);
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 pb-20">
      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-br from-shopee to-shopee-dark z-0"></div>

      <div className="relative z-10 container mx-auto px-4 pt-8 max-w-3xl">
        {/* Header */}
        <div className="flex justify-between items-center mb-8 text-white">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm">
              <ShoppingBag className="w-8 h-8 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight">ShopeeLink AI Pro</h1>
              <p className="text-white/80 text-sm">Affiliate Tool & Marketing Generator</p>
            </div>
          </div>
          <button
            onClick={() => setIsSettingsOpen(true)}
            className="flex items-center gap-2 bg-white/10 hover:bg-white/20 transition px-4 py-2 rounded-lg backdrop-blur-sm text-sm font-medium"
          >
            <Settings className="w-4 h-4" />
            <span>Cấu hình</span>
          </button>
        </div>

        {/* Warning if no ID */}
        {!settings.affiliateId && (
          <div className="bg-yellow-50 border border-yellow-200 text-yellow-800 px-4 py-3 rounded-xl mb-6 flex items-start gap-3 shadow-sm animate-bounce-short">
            <Settings className="w-5 h-5 shrink-0 mt-0.5" />
            <div>
              <p className="font-bold">Chưa nhập Affiliate ID</p>
              <p className="text-sm mt-1">Vui lòng vào <button onClick={()=>setIsSettingsOpen(true)} className="underline font-semibold">Cài đặt</button> để nhập ID Affiliate của bạn trước khi sử dụng.</p>
            </div>
          </div>
        )}

        {/* Input Card */}
        <div className="bg-white rounded-2xl shadow-xl p-6 mb-8">
          <label className="block text-sm font-semibold text-gray-700 mb-2 ml-1">
            Dán link Shopee sản phẩm
          </label>
          <div className="relative">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
              <LinkIcon className="w-5 h-5" />
            </div>
            <input
              type="text"
              value={urlInput}
              onChange={(e) => setUrlInput(e.target.value)}
              placeholder="https://shopee.vn/..."
              className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-shopee focus:border-transparent outline-none transition text-base"
              onKeyDown={(e) => e.key === 'Enter' && convertLink()}
            />
          </div>

          {error && <p className="text-red-500 text-sm mt-2 ml-1 flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-red-500 inline-block"></span>{error}</p>}

          <button
            onClick={convertLink}
            className="w-full mt-4 bg-gradient-to-r from-shopee to-shopee-dark hover:from-shopee-light hover:to-shopee text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-orange-200 transition transform active:scale-[0.99] flex justify-center items-center gap-2"
          >
            <Zap className="w-5 h-5" fill="currentColor" />
            Chuyển Đổi Link Ngay
          </button>
        </div>

        {/* Result Area */}
        {currentResult && (
          <div className="mb-10">
            <ResultCard result={currentResult} />
          </div>
        )}

        {/* History */}
        {history.length > 0 && (
          <div className="mt-8">
             <div className="flex justify-between items-end mb-4 px-1">
               <h3 className="font-bold text-gray-700 text-lg">Lịch sử chuyển đổi</h3>
               <button onClick={handleClearHistory} className="text-xs text-gray-400 hover:text-red-500">Xóa lịch sử</button>
             </div>
             <div className="space-y-3">
               {history.map((item, idx) => (
                 <div key={idx} onClick={() => setCurrentResult(item)} className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition cursor-pointer group">
                    <p className="text-xs text-gray-400 mb-1">{new Date(item.timestamp).toLocaleString()}</p>
                    <p className="text-sm text-gray-800 truncate font-medium group-hover:text-shopee transition">{item.originalUrl}</p>
                 </div>
               ))}
             </div>
          </div>
        )}

        <div className="mt-12 text-center">
            <p className="text-gray-400 text-sm">Powered by Gemini AI ✦ React ✦ Tailwind</p>
        </div>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings}
        onSave={saveSettings}
      />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Link as LinkIcon, ShoppingBag, Zap } from 'lucide-react';
import { ResultCard } from './components/ResultCard';
import { UserSettings, ConvertedLink } from './types';

// Constants
// Hardcoded settings as requested by the user
const DEFAULT_SETTINGS: UserSettings = {
  affiliateId: '17362210029',
  subId: 'Web Tool',
  universalLinkEnabled: true,
};

const HISTORY_KEY = 'shopee_link_history';

function App() {
  const [urlInput, setUrlInput] = useState('');
  // Use constant settings directly since configuration UI is removed
  const settings = DEFAULT_SETTINGS;

  const [currentResult, setCurrentResult] = useState<ConvertedLink | null>(null);
  const [history, setHistory] = useState<ConvertedLink[]>([]);
  const [error, setError] = useState('');

  // Load history on mount
  useEffect(() => {
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      setHistory(JSON.parse(savedHistory));
    }
  }, []);

  const convertLink = () => {
    setError('');

    // Basic validation
    if (!urlInput.trim()) {
      setError('Vui lòng nhập link Shopee');
      return;
    }
    if (!urlInput.includes('shopee') && !urlInput.includes('shp.ee')) {
      setError('Link không hợp lệ. Vui lòng nhập link Shopee (shopee.vn hoặc shp.ee)');
      return;
    }

    // --- CONVERSION LOGIC ---
    let affiliateUrl = '';

    if (settings.universalLinkEnabled) {
      // Construction for Universal Link (Deep Link) pattern
      // Often looks like: https://shopee.vn/universal-link/[slug]?referrer=[aff_id]

      try {
        const urlObj = new URL(urlInput);

        // Handle short links (shp.ee)
        if (urlInput.includes('shp.ee')) {
           const separator = urlInput.includes('?') ? '&' : '?';
           affiliateUrl = `${urlInput}${separator}utm_source=${settings.affiliateId}`;
        } else {
           // Standard shopee.vn link
           const path = urlObj.pathname;
           // Universal Link base
           const baseUniversal = 'https://shopee.vn/universal-link';

           // Construct new params
           const params = new URLSearchParams();
           params.append('utm_source', settings.affiliateId);
           if (settings.subId) params.append('utm_content', settings.subId);
           params.append('deep_and_deferred', '1');

           affiliateUrl = `${baseUniversal}${path}?${params.toString()}`;
        }
      } catch (e) {
        // Fallback simple append
        const separator = urlInput.includes('?') ? '&' : '?';
        affiliateUrl = `${urlInput}${separator}utm_source=${settings.affiliateId}`;
      }
    } else {
      // Simple UTM Append
      const separator = urlInput.includes('?') ? '&' : '?';
      let suffix = `utm_source=${settings.affiliateId}`;
      if (settings.subId) suffix += `&utm_content=${settings.subId}`;
      affiliateUrl = `${urlInput}${separator}${suffix}`;
    }

    const newResult: ConvertedLink = {
      originalUrl: urlInput,
      affiliateUrl: affiliateUrl,
      timestamp: Date.now(),
    };

    setCurrentResult(newResult);

    // Update history
    const newHistory = [newResult, ...history].slice(0, 10); // Keep last 10
    setHistory(newHistory);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
  };

  const handleClearHistory = () => {
    setHistory([]);
    localStorage.removeItem(HISTORY_KEY);
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 pb-20">
      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-br from-shopee to-shopee-dark z-0"></div>

      <div className="relative z-10 container mx-auto px-4 pt-8 max-w-3xl">
        {/* Header */}
        <div className="flex justify-between items-center mb-8 text-white">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm">
              <ShoppingBag className="w-8 h-8 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight">ShopeeLink AI Pro</h1>
              <p className="text-white/80 text-sm">Công cụ lấy link Affiliate & Content AI</p>
            </div>
          </div>
          {/* Settings button removed as settings are now hardcoded */}
        </div>

        {/* Input Card */}
        <div className="bg-white rounded-2xl shadow-xl p-6 mb-8">
          <label className="block text-sm font-semibold text-gray-700 mb-2 ml-1">
            Dán link Shopee cần chuyển đổi
          </label>
          <div className="relative">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
              <LinkIcon className="w-5 h-5" />
            </div>
            <input
              type="text"
              value={urlInput}
              onChange={(e) => setUrlInput(e.target.value)}
              placeholder="https://shopee.vn/..."
              className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-shopee focus:border-transparent outline-none transition text-base"
              onKeyDown={(e) => e.key === 'Enter' && convertLink()}
            />
          </div>

          {error && <p className="text-red-500 text-sm mt-2 ml-1 flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-red-500 inline-block"></span>{error}</p>}

          <button
            onClick={convertLink}
            className="w-full mt-4 bg-gradient-to-r from-shopee to-shopee-dark hover:from-shopee-light hover:to-shopee text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-orange-200 transition transform active:scale-[0.99] flex justify-center items-center gap-2"
          >
            <Zap className="w-5 h-5" fill="currentColor" />
            Chuyển Đổi Ngay
          </button>
        </div>

        {/* Result Area */}
        {currentResult && (
          <div className="mb-10">
            <ResultCard result={currentResult} />
          </div>
        )}

        {/* History */}
        {history.length > 0 && (
          <div className="mt-8">
             <div className="flex justify-between items-end mb-4 px-1">
               <h3 className="font-bold text-gray-700 text-lg">Lịch sử</h3>
               <button onClick={handleClearHistory} className="text-xs text-gray-400 hover:text-red-500">Xóa lịch sử</button>
             </div>
             <div className="space-y-3">
               {history.map((item, idx) => (
                 <div key={idx} onClick={() => setCurrentResult(item)} className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition cursor-pointer group">
                    <p className="text-xs text-gray-400 mb-1">{new Date(item.timestamp).toLocaleString()}</p>
                    <p className="text-sm text-gray-800 truncate font-medium group-hover:text-shopee transition">{item.originalUrl}</p>
                 </div>
               ))}
             </div>
          </div>
        )}

        <div className="mt-12 text-center">
            <p className="text-gray-400 text-sm">Powered by Gemini AI ✦ React ✦ Tailwind</p>
        </div>
      </div>
    </div>
  );
}

export default App;

// Service to handle URL shortening
// Note: The user requested by.com.vn, but it requires a private API Key and often has CORS restrictions for browser-only apps.
// We use TinyURL as a robust, configuration-free alternative that works immediately.

export const shortenUrl = async (url: string): Promise<string> => {
  try {
    // Using TinyURL API (Free, no key required, CORS enabled)
    const response = await fetch(`https://tinyurl.com/api-create.php?url=${encodeURIComponent(url)}`);

    if (!response.ok) {
      throw new Error('Network response was not ok');
    }

    const shortUrl = await response.text();
    return shortUrl;
  } catch (error) {
    console.error("Error shortening URL:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Copy, Check, ExternalLink, Wand2, RefreshCw, Scissors, Link as LinkIcon } from 'lucide-react';
import { ConvertedLink, MarketingContent, Platform } from '../types';
import { generateMarketingCopy } from '../services/geminiService';
import { shortenUrl } from '../services/shortenerService';

interface ResultCardProps {
  result: ConvertedLink;
}

export const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [copied, setCopied] = useState(false);
  const [copiedShort, setCopiedShort] = useState(false);
  const [copiedText, setCopiedText] = useState(false);

  const [shortenedUrl, setShortenedUrl] = useState<string>('');
  const [isShortening, setIsShortening] = useState(false);

  const [marketingContent, setMarketingContent] = useState<MarketingContent | null>(null);
  const [loadingAI, setLoadingAI] = useState(false);
  const [platform, setPlatform] = useState<Platform>('facebook');

  // Reset state when result changes
  useEffect(() => {
    setShortenedUrl('');
    setMarketingContent(null);
  }, [result]);

  const handleCopy = (text: string, type: 'main' | 'short' | 'content') => {
    navigator.clipboard.writeText(text);
    if (type === 'main') {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } else if (type === 'short') {
      setCopiedShort(true);
      setTimeout(() => setCopiedShort(false), 2000);
    } else {
      setCopiedText(true);
      setTimeout(() => setCopiedText(false), 2000);
    }
  };

  const handleShortenLink = async () => {
    setIsShortening(true);
    try {
      const short = await shortenUrl(result.affiliateUrl);
      setShortenedUrl(short);
    } catch (error) {
      alert("Không thể rút gọn link lúc này. Vui lòng thử lại sau.");
    } finally {
      setIsShortening(false);
    }
  };

  const handleGenerateAI = async () => {
    setLoadingAI(true);
    try {
      const content = await generateMarketingCopy(result.originalUrl, platform);
      setMarketingContent(content);
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingAI(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden animate-slide-up">
      {/* Header */}
      <div className="bg-gray-50 p-4 border-b border-gray-100 flex items-center justify-between">
        <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Link Affiliate Của Bạn</span>
        <span className="text-xs text-gray-400">{new Date(result.timestamp).toLocaleTimeString()}</span>
      </div>

      {/* Main Link Area */}
      <div className="p-6">
        {/* Original Affiliate Link */}
        <div className="mb-4">
          <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Link Affiliate Gốc</label>
          <div className="flex flex-col sm:flex-row gap-3 items-center">
            <div className="flex-1 w-full relative">
              <input
                readOnly
                value={result.affiliateUrl}
                className="w-full bg-orange-50/50 text-gray-600 border border-orange-100 rounded-lg px-4 py-2.5 pr-12 font-mono text-sm focus:outline-none"
              />
              <a 
                href={result.affiliateUrl} 
                target="_blank" 
                rel="noreferrer"
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-shopee"
                title="Mở link"
              >
                <ExternalLink className="w-4 h-4" />
              </a>
            </div>
            <button
              onClick={() => handleCopy(result.affiliateUrl, 'main')}
              className={`shrink-0 px-4 py-2.5 rounded-lg font-medium text-sm flex items-center justify-center gap-2 transition-all duration-200 border ${
                copied 
                  ? 'bg-green-50 text-green-600 border-green-200' 
                  : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
              }`}
            >
              {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              {copied ? 'Đã Copy' : 'Copy'}
            </button>
          </div>
        </div>

        {/* Action Buttons or Shortened Link */}
        {!shortenedUrl ? (
          <div className="flex justify-start">
             <button
              onClick={handleShortenLink}
              disabled={isShortening}
              className="px-5 py-2.5 bg-gray-900 hover:bg-black text-white rounded-lg font-medium shadow-md shadow-gray-200 flex items-center gap-2 transition transform active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isShortening ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Scissors className="w-4 h-4" />}
              {isShortening ? 'Đang xử lý...' : 'Rút Gọn Link'}
            </button>
          </div>
        ) : (
          <div className="animate-fade-in">
             <label className="block text-xs font-semibold text-shopee mb-1.5 ml-1 flex items-center gap-1">
               <LinkIcon className="w-3 h-3"/> Link Rút Gọn
             </label>
             <div className="flex flex-col sm:flex-row gap-3 items-center">
              <div className="flex-1 w-full relative">
                <input
                  readOnly
                  value={shortenedUrl}
                  className="w-full bg-white text-shopee border-2 border-shopee/20 rounded-lg px-4 py-3 pr-12 font-mono text-base font-semibold focus:outline-none shadow-sm"
                />
                <a 
                  href={shortenedUrl} 
                  target="_blank" 
                  rel="noreferrer"
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-shopee hover:text-shopee-dark"
                  title="Mở link"
                >
                  <ExternalLink className="w-4 h-4" />
                </a>
              </div>
              <button
                onClick={() => handleCopy(shortenedUrl, 'short')}
                className={`w-full sm:w-auto px-6 py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-all duration-200 shadow-md ${
                  copiedShort 
                    ? 'bg-green-500 text-white shadow-green-200' 
                    : 'bg-shopee text-white hover:bg-shopee-dark shadow-orange-200'
                }`}
              >
                {copiedShort ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                {copiedShort ? 'Đã Copy' : 'Copy Link'}
              </button>
            </div>
          </div>
        )}

        {/* AI Section */}
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              <Wand2 className="w-5 h-5 text-purple-600" />
              Tạo Caption Bán Hàng (AI)
            </h3>

            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg">
              {(['facebook', 'tiktok', 'instagram'] as Platform[]).map((p) => (
                <button
                  key={p}
                  onClick={() => setPlatform(p)}
                  className={`px-3 py-1.5 rounded-md text-xs font-medium capitalize transition ${
                    platform === p ? 'bg-white shadow text-gray-900' : 'text-gray-500 hover:text-gray-700'
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>

          {!marketingContent && !loadingAI && (
             <div className="bg-purple-50 rounded-xl p-6 text-center border border-purple-100">
               <p className="text-purple-800 mb-4 font-medium">Sử dụng Gemini để viết content bán hàng tự động cho link này.</p>
               <button
                 onClick={handleGenerateAI}
                 className="px-6 py-2.5 bg-purple-600 hover:bg-purple-700 text-white rounded-full font-medium shadow-md shadow-purple-200 flex items-center gap-2 mx-auto transition transform hover:scale-105"
               >
                 <Wand2 className="w-4 h-4" />
                 Viết Content Ngay
               </button>
             </div>
          )}

          {loadingAI && (
            <div className="bg-gray-50 rounded-xl p-8 flex flex-col items-center justify-center animate-pulse">
              <RefreshCw className="w-8 h-8 text-purple-500 animate-spin mb-3" />
              <p className="text-gray-500 font-medium">Gemini đang phân tích sản phẩm và viết bài...</p>
            </div>
          )}

          {marketingContent && !loadingAI && (
            <div className="bg-white rounded-xl border border-purple-100 shadow-sm overflow-hidden">
               <div className="p-4 bg-purple-50 border-b border-purple-100 flex justify-between items-center">
                 <span className="text-xs font-bold text-purple-700 uppercase">Gemini Output ({platform})</span>
                 <button 
                  onClick={() => handleCopy(`${marketingContent.caption}\n\n${marketingContent.hashtags.join(' ')}\n\nLink mua: ${shortenedUrl || result.affiliateUrl}`, 'content')}
                  className="text-purple-600 hover:text-purple-800 text-xs font-medium flex items-center gap-1"
                 >
                   {copiedText ? <Check className="w-3 h-3"/> : <Copy className="w-3 h-3"/>}
                   {copiedText ? 'Đã sao chép' : 'Sao chép toàn bộ'}
                 </button>
               </div>
               <div className="p-5">
                 <p className="text-gray-800 whitespace-pre-line leading-relaxed mb-4 text-sm sm:text-base">
                   {marketingContent.caption}
                 </p>
                 <div className="flex flex-wrap gap-2 text-sm text-blue-600 font-medium">
                   {marketingContent.hashtags.join(' ')}
                 </div>
                 <div className="mt-4 pt-4 border-t border-dashed border-gray-200 text-sm text-gray-500">
                   Link mua: <span className="text-shopee font-mono">{shortenedUrl || result.affiliateUrl}</span>
                 </div>
               </div>
               <div className="bg-gray-50 p-3 text-center">
                  <button 
                    onClick={handleGenerateAI}
                    className="text-gray-500 hover:text-purple-600 text-sm font-medium flex items-center justify-center gap-2 mx-auto"
                  >
                    <RefreshCw className="w-4 h-4" />
                    Viết lại phiên bản khác
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Copy, Check, ExternalLink, Wand2, RefreshCw, Link as LinkIcon } from 'lucide-react';
import { ConvertedLink, MarketingContent, Platform } from '../types';
import { generateMarketingCopy } from '../services/geminiService';
import { shortenUrl } from '../services/shortenerService';

interface ResultCardProps {
  result: ConvertedLink;
}

export const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [copied, setCopied] = useState(false);
  const [copiedText, setCopiedText] = useState(false);

  const [displayUrl, setDisplayUrl] = useState<string>('');
  const [isShortening, setIsShortening] = useState(false);

  const [marketingContent, setMarketingContent] = useState<MarketingContent | null>(null);
  const [loadingAI, setLoadingAI] = useState(false);
  const [platform, setPlatform] = useState<Platform>('facebook');

  // Automatically shorten link when result changes
  useEffect(() => {
    let isMounted = true;
    const processLink = async () => {
      setIsShortening(true);
      setDisplayUrl('');
      setMarketingContent(null);

      try {
        const short = await shortenUrl(result.affiliateUrl);
        if (isMounted) setDisplayUrl(short);
      } catch (error) {
        console.error("Shortening failed, falling back to original", error);
        if (isMounted) setDisplayUrl(result.affiliateUrl);
      } finally {
        if (isMounted) setIsShortening(false);
      }
    };

    processLink();

    return () => {
      isMounted = false;
    };
  }, [result]);

  const handleCopy = (text: string, type: 'link' | 'content') => {
    navigator.clipboard.writeText(text);
    if (type === 'link') {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } else {
      setCopiedText(true);
      setTimeout(() => setCopiedText(false), 2000);
    }
  };

  const handleGenerateAI = async () => {
    setLoadingAI(true);
    try {
      const content = await generateMarketingCopy(result.originalUrl, platform);
      setMarketingContent(content);
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingAI(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden animate-slide-up">
      {/* Header */}
      <div className="bg-gray-50 p-4 border-b border-gray-100 flex items-center justify-between">
        <span className="text-xs font-bold text-gray-500 uppercase tracking-wider flex items-center gap-2">
          <LinkIcon className="w-3 h-3" /> Link Rút Gọn
        </span>
        <span className="text-xs text-gray-400">{new Date(result.timestamp).toLocaleTimeString()}</span>
      </div>

      {/* Main Link Area */}
      <div className="p-6">
        <div className="mb-2">
          <div className="flex flex-col sm:flex-row gap-3 items-center">
            <div className="flex-1 w-full relative">
              <input
                readOnly
                value={isShortening ? 'Đang tạo link rút gọn...' : displayUrl}
                className={`w-full border-2 rounded-lg px-4 py-3 pr-12 font-mono text-base font-semibold focus:outline-none shadow-sm transition-colors ${
                  isShortening 
                    ? 'bg-gray-50 text-gray-400 border-gray-100 italic' 
                    : 'bg-white text-shopee border-shopee/20'
                }`}
              />
              {!isShortening && displayUrl && (
                <a 
                  href={displayUrl} 
                  target="_blank" 
                  rel="noreferrer"
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-shopee hover:text-shopee-dark"
                  title="Mở link"
                >
                  <ExternalLink className="w-4 h-4" />
                </a>
              )}
            </div>
            <button
              onClick={() => handleCopy(displayUrl, 'link')}
              disabled={isShortening}
              className={`w-full sm:w-auto px-6 py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-all duration-200 shadow-md ${
                copied 
                  ? 'bg-green-500 text-white shadow-green-200' 
                  : isShortening
                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                    : 'bg-shopee text-white hover:bg-shopee-dark shadow-orange-200'
              }`}
            >
              {isShortening ? (
                <RefreshCw className="w-5 h-5 animate-spin" />
              ) : copied ? (
                <Check className="w-5 h-5" />
              ) : (
                <Copy className="w-5 h-5" />
              )}
              {copied ? 'Đã Copy' : 'Copy Link'}
            </button>
          </div>
        </div>

        {/* AI Section */}
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              <Wand2 className="w-5 h-5 text-purple-600" />
              Tạo Caption Bán Hàng (AI)
            </h3>

            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg">
              {(['facebook', 'tiktok', 'instagram'] as Platform[]).map((p) => (
                <button
                  key={p}
                  onClick={() => setPlatform(p)}
                  className={`px-3 py-1.5 rounded-md text-xs font-medium capitalize transition ${
                    platform === p ? 'bg-white shadow text-gray-900' : 'text-gray-500 hover:text-gray-700'
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>

          {!marketingContent && !loadingAI && (
             <div className="bg-purple-50 rounded-xl p-6 text-center border border-purple-100">
               <p className="text-purple-800 mb-4 font-medium">Sử dụng Gemini để viết content bán hàng tự động cho link này.</p>
               <button
                 onClick={handleGenerateAI}
                 disabled={isShortening}
                 className="px-6 py-2.5 bg-purple-600 hover:bg-purple-700 text-white rounded-full font-medium shadow-md shadow-purple-200 flex items-center gap-2 mx-auto transition transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed"
               >
                 <Wand2 className="w-4 h-4" />
                 Viết Content Ngay
               </button>
             </div>
          )}

          {loadingAI && (
            <div className="bg-gray-50 rounded-xl p-8 flex flex-col items-center justify-center animate-pulse">
              <RefreshCw className="w-8 h-8 text-purple-500 animate-spin mb-3" />
              <p className="text-gray-500 font-medium">Gemini đang phân tích sản phẩm và viết bài...</p>
